import { describe, expect, it } from 'vitest';
import { stripReleaseVersionHeading } from './release-notes';

describe('stripReleaseVersionHeading', () => {
  it('removes a duplicated release-version heading and following blank lines', () => {
    expect(stripReleaseVersionHeading('# v1.2.3\n\n## What changed\n\n- Fix', '1.2.3'))
      .toBe('## What changed\n\n- Fix');
  });

  it('removes a plain version heading', () => {
    expect(stripReleaseVersionHeading('## Release 1.2.3 ##\n\nNotes', 'v1.2.3'))
      .toBe('Notes');
  });

  it('removes a version heading with a release date', () => {
    expect(stripReleaseVersionHeading('## v1.2.3 (2026-10-21)\n\n## Changes\n\n- Fix', '1.2.3'))
      .toBe('## Changes\n\n- Fix');
  });

  it('keeps meaningful headings that do not duplicate the version', () => {
    const changelog = '## What changed\n\n- Fix';
    expect(stripReleaseVersionHeading(changelog, '1.2.3')).toBe(changelog);
  });

  it('keeps text without a markdown heading', () => {
    const changelog = 'Fixed an issue.';
    expect(stripReleaseVersionHeading(changelog, '1.2.3')).toBe(changelog);
  });
});
